        Deque<Integer> q=new ArrayDeque<>();
        int[] result=new int[numbers.length-target+1];
        for (int i=0; i<numbers.length; i++) {
            while (!q.isEmpty() && q.peekFirst() <= i-target) q.removeFirst();
            while (!q.isEmpty() && numbers[q.peekLast()] <= numbers[i]) q.removeLast();
