class Solution {
    public int[] solve(int[] numbers, int target) {
        int[][] pairs=new int[numbers.length/2][2];
        for(int i=0;i<pairs.length;i++) pairs[i]=new int[]{numbers[2*i],numbers[2*i+1]};
        Arrays.sort(pairs,Comparator.comparingInt(a -> a[0]));
        ArrayList<Integer> result=new ArrayList<>();
        for(int[] p:pairs) {
            int n=result.size();
            if(n>0 && p[0]<=result.get(n-1)) result.set(n-1,Math.max(result.get(n-1),p[1]));
            else {result.add(p[0]);result.add(p[1]);}
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }
}

